  1→/**
  2→ * FastAPI Client for ZakupPro
  3→ *
  4→ * Provides a typed fetch wrapper for communicating with the FastAPI backend.
  5→ * Handles authentication, error transformation, and standard request/response processing.
  6→ */
  7→
  8→import type { ApiError } from '@/types/fastapi';
  9→
 10→// =============================================================================
 11→// Configuration
 12→// =============================================================================
 13→
 14→const FASTAPI_URL = process.env.FASTAPI_URL || 'http://localhost:8000';
 15→const FASTAPI_AUTH_TOKEN = process.env.FASTAPI_AUTH_TOKEN;
 16→
 17→// =============================================================================
 18→// Types
 19→// =============================================================================
 20→
 21→export interface RequestOptions {
 22→  method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
 23→  body?: unknown;
 24→  headers?: Record<string, string>;
 25→  params?: Record<string, string | number | boolean | undefined>;
 26→}
 27→
 28→export interface ApiResult<T> {
 29→  data: T | null;
 30→  error: ApiError | null;
 31→}
 32→
 33→// =============================================================================
 34→// Error Handling
 35→// =============================================================================
 36→
 37→class ApiError_ extends Error {
 38→  status: number;
 39→  details?: unknown;
 40→
 41→  constructor(message: string, status: number, details?: unknown) {
 42→    super(message);
 43→    this.name = 'ApiError';
 44→    this.status = status;
 45→    this.details = details;
 46→  }
 47→}
 48→
 49→/**
 50→ * Transform FastAPI HTTPException response into standard ApiError format
 51→ */
 52→function transformError(response: Response, body?: unknown): ApiError {
 53→  const status = response.status;
 54→
 55→  // FastAPI HTTPException format: { "detail": string | object }
 56→  let message = 'An error occurred';
 57→  let details: unknown;
 58→
 59→  if (body && typeof body === 'object' && 'detail' in body) {
 60→    const detail = body.detail;
 61→    if (typeof detail === 'string') {
 62→      message = detail;
 63→    } else if (detail && typeof detail === 'object') {
 64→      message = 'API request failed';
 65→      details = detail;
 66→    }
 67→  } else if (body && typeof body === 'string') {
 68→    message = body;
 69→  } else {
 70→    message = response.statusText || `HTTP ${status}`;
 71→  }
 72→
 73→  return { error: message, details };
 74→}
 75→
 76→/**
 77→ * Build query string from params object
 78→ */
 79→function buildQueryString(params: Record<string, string | number | boolean | undefined>): string {
 80→  const searchParams = new URLSearchParams();
 81→  for (const [key, value] of Object.entries(params)) {
 82→    if (value !== undefined) {
 83→      searchParams.append(key, String(value));
 84→    }
 85→  }
 86→  const queryString = searchParams.toString();
 87→  return queryString ? `?${queryString}` : '';
 88→}
 89→
 90→// =============================================================================
 91→// API Client
 92→// =============================================================================
 93→
 94→/**
 95→ * Core fetch function with error handling and authentication
 96→ */
 97→export async function apiFetch<T>(
 98→  endpoint: string,
 99→  options: RequestOptions = {}
100→): Promise<ApiResult<T>> {
101→  const url = `${FASTAPI_URL}${endpoint}`;
102→
103→  const headers: Record<string, string> = {
104→    'Content-Type': 'application/json',
105→    ...options.headers,
106→  };
107→
108→  // Add Authorization header if token is configured
109→  if (FASTAPI_AUTH_TOKEN) {
110→    headers['Authorization'] = `Bearer ${FASTAPI_AUTH_TOKEN}`;
111→  }
112→
113→  const config: RequestInit = {
114→    method: options.method || 'GET',
115→    headers,
116→  };
117→
118→  if (options.body) {
119→    config.body = JSON.stringify(options.body);
120→  }
121→
122→  // Add query parameters if provided
123→  let fullUrl = url;
124→  if (options.params) {
125→    fullUrl += buildQueryString(options.params);
126→  }
127→
128→  try {
129→    const response = await fetch(fullUrl, config);
130→
131→    // Handle 204 No Content (successful delete, etc.)
132→    if (response.status === 204) {
133→      return { data: null as T, error: null };
134→    }
135→
136→    // Parse JSON body
137→    let body: unknown;
138→    const contentType = response.headers.get('content-type');
139→    if (contentType?.includes('application/json')) {
140→      body = await response.json();
141→    } else {
142→      body = await response.text();
143→    }
144→
145→    // Check for error status
146→    if (!response.ok) {
147→      const error = transformError(response, body);
148→      return { data: null, error };
149→    }
150→
151→    return { data: body as T, error: null };
152→  } catch (err) {
153→    // Network errors, fetch errors, etc.
154→    const error: ApiError = {
155→      error: err instanceof Error ? err.message : 'Network error',
156→    };
157→    return { data: null, error };
158→  }
159→}
160→
161→// =============================================================================
162→// HTTP Method Helpers
163→// =============================================================================
164→
165→export async function get<T>(
166→  endpoint: string,
167→  params?: Record<string, string | number | boolean | undefined>
168→): Promise<ApiResult<T>> {
169→  return apiFetch<T>(endpoint, { method: 'GET', params });
170→}
171→
172→export async function post<T>(
173→  endpoint: string,
174→  body?: unknown
175→): Promise<ApiResult<T>> {
176→  return apiFetch<T>(endpoint, { method: 'POST', body });
177→}
178→
179→export async function put<T>(
180→  endpoint: string,
181→  body?: unknown
182→): Promise<ApiResult<T>> {
183→  return apiFetch<T>(endpoint, { method: 'PUT', body });
184→}
185→
186→export async function patch<T>(
187→  endpoint: string,
188→  body?: unknown
189→): Promise<ApiResult<T>> {
190→  return apiFetch<T>(endpoint, { method: 'PATCH', body });
191→}
192→
193→export async function del<T>(
194→  endpoint: string
195→): Promise<ApiResult<T>> {
196→  return apiFetch<T>(endpoint, { method: 'DELETE' });
197→}
198→
199→// =============================================================================
200→// Convenience Functions
201→// =============================================================================
202→
203→/**
204→ * Throws an error if the API result contains an error
205→ * Useful for handling API responses in a try/catch pattern
206→ */
207→export function throwErrorOnError<T>(result: ApiResult<T>): T {
208→  if (result.error) {
209→    throw new ApiError_(
210→      result.error.error,
211→      0, // Status not available in ApiResult
212→      result.error.details
213→    );
214→  }
215→  return result.data as T;
216→}
217→
218→/**
219→ * Check if the API result is successful
220→ */
221→export function isSuccess<T>(result: ApiResult<T>): result is ApiResult<T> & { data: T } {
222→  return result.error === null && result.data !== null;
223→}
224→
225→/**
226→ * Check if the API result failed
227→ */
228→export function isFailure<T>(result: ApiResult<T>): result is ApiResult<T> & { error: ApiError } {
229→  return result.error !== null;
230→}
231→
232→// =============================================================================
233→// Export default client object
234→// =============================================================================
235→
236→export const apiClient = {
237→  get,
238→  post,
239→  put,
240→  patch,
241→  delete: del,
242→  fetch: apiFetch,
243→};
244→
245→export default apiClient;
246→

